{{--
    Des boutons à presser qui vont ensemble.
      - `type="single"` (défaut) : une valeur, comme des boutons radio ;
        `required` empêche de la retirer ;
      - `type="multiple"` : un tableau, chaque bouton est indépendant.

    <x-ui.toggle-group wire:model.live="align" label="Alignment">
        <x-ui.toggle-group.item value="left" aria-label="Align left">…</x-ui.toggle-group.item>
    </x-ui.toggle-group>

    Variantes : `ghost` (barre d'outils), `outline` (boutons accolés),
    `segmented` (rail et curseur, comme des onglets). Une tabulation entre
    dans le groupe, les flèches se déplacent dedans.
    Moteur : Alpine.data('fwToggleGroup'), resources/js/plugins/toggle-group.js.
--}}
@props([
    'type' => 'single',
    'value' => null,
    'name' => null,
    'label' => null,
    'options' => null,
    'optionValue' => 'value',
    'optionLabel' => 'label',
    'optionIcon' => 'icon',
    'variant' => 'ghost',
    'size' => 'md',
    'orientation' => 'horizontal',
    'required' => false,
    'disabled' => false,
])

@php
    $type = $type === 'multiple' ? 'multiple' : 'single';
    $variant = in_array($variant, ['ghost', 'outline', 'segmented'], true) ? $variant : 'ghost';
    $vertical = $orientation === 'vertical';
    $initial = \App\Flexiwind\OptionList::selected($value);
    $items = \App\Flexiwind\OptionList::normalize($options, ['value' => $optionValue, 'label' => $optionLabel, 'icon' => $optionIcon]);
@endphp

<div data-slot="toggle-group" role="{{ $type === 'single' ? 'radiogroup' : 'group' }}"
    @if ($label) aria-label="{{ $label }}" @endif
    @if ($vertical) aria-orientation="vertical" @endif
    @if ($disabled) aria-disabled="true" @endif
    x-data="fwToggleGroup(@js([
        'multiple' => $type === 'multiple',
        'value' => $type === 'multiple' ? $initial : ($initial[0] ?? null),
        'required' => (bool) $required,
        'name' => $name,
    ]))"
    x-modelable="value"
    x-on:keydown="onKeydown($event)"
    {{ $attributes->class([
        '[--toggle-group-padding:--spacing(0.75)] isolate inline-flex',
        'flex-col items-stretch' => $vertical,
        'items-center' => ! $vertical,
        'gap-0.5 rounded-ui border border-border bg-background p-(--toggle-group-padding) shadow-xs' => $variant === 'ghost',
        'gap-0.5 rounded-ui bg-muted p-(--toggle-group-padding)' => $variant === 'segmented',
    ]) }}>
    @foreach ($items as $item)
        <x-ui.toggle-group.item :value="$item['value']" :disabled="$item['disabled']" :aria-label="$item['icon'] && $item['label'] === $item['value'] ? $item['label'] : null">
            @if ($item['icon'])
                <x-ui.icon :name="$item['icon']" />
            @endif
            @unless ($item['icon'] && $item['label'] === $item['value'])
                <span>{{ $item['label'] }}</span>
            @endunless
        </x-ui.toggle-group.item>
    @endforeach
    {{ $slot }}

    @if ($name)
        <div wire:ignore hidden>
            <template x-for="(item, index) in formValues" :key="index">
                <input type="hidden" :name="inputName" :value="item">
            </template>
        </div>
    @endif
</div>

{{--
    Un bouton d'un <x-ui.toggle-group>. Une icône seule demande un
    aria-label ; un texte se suffit.
--}}
@aware(['type' => 'single', 'variant' => 'ghost', 'size' => 'md', 'orientation' => 'horizontal', 'disabled' => false])
@props(['value', 'type' => 'single', 'variant' => 'ghost', 'size' => 'md', 'orientation' => 'horizontal', 'disabled' => false])

@php
    $single = $type !== 'multiple';
    $variant = in_array($variant, ['ghost', 'outline', 'segmented'], true) ? $variant : 'ghost';
    $size = in_array($size, ['sm', 'md', 'lg'], true) ? $size : 'md';
    $vertical = $orientation === 'vertical';
    $inset = $variant !== 'outline';
    $value = (string) $value;
@endphp

<button type="button" data-slot="toggle-group-item" data-value="{{ $value }}" data-toggle-stop
    role="{{ $single ? 'radio' : 'button' }}"
    @if ($single)
        aria-checked="false" x-bind:aria-checked="String(fwIsOn(@js($value)))"
    @else
        aria-pressed="false" x-bind:aria-pressed="String(fwIsOn(@js($value)))"
    @endif
    x-bind:data-on="fwIsOn(@js($value)) ? '' : null"
    x-on:click="fwToggle(@js($value))"
    @if ($disabled) disabled @endif
    {{ $attributes->class([
        'relative inline-flex shrink-0 items-center gap-2 font-medium whitespace-nowrap transition-colors duration-150',
        'outline-2 -outline-offset-1 outline-transparent focus-visible:z-20 focus-visible:outline-(--ui-input-focus-outline) disabled:cursor-not-allowed disabled:opacity-50',
        '*:data-[slot=icon]:shrink-0',
        'w-full justify-start' => $vertical,
        'justify-center' => ! $vertical,
        // Posé dans un rail : le rayon du groupe moins son padding.
        'rounded-[calc(var(--radius-ui)-var(--toggle-group-padding))]' => $inset,
        'h-6.5 min-w-6.5 px-1.5 text-[13px]' => $inset && $size === 'sm',
        'h-7.5 min-w-7.5 px-2 text-sm' => $inset && $size === 'md',
        'h-8.5 min-w-8.5 px-2.5 text-sm' => $inset && $size === 'lg',
        'text-muted-foreground enabled:hover:bg-muted enabled:hover:text-title-foreground data-on:bg-muted data-on:text-title-foreground' => $variant === 'ghost',
        'text-muted-foreground enabled:hover:text-title-foreground data-on:bg-background data-on:text-title-foreground data-on:shadow-xs data-on:ring-1 data-on:ring-border' => $variant === 'segmented',
        // Accolés : seuls les bouts du groupe sont arrondis.
        'h-8 min-w-8 px-2.5 text-[13px]' => ! $inset && $size === 'sm',
        'h-9 min-w-9 px-3 text-sm' => ! $inset && $size === 'md',
        'h-10 min-w-10 px-3.5 text-sm' => ! $inset && $size === 'lg',
        'border border-border-input bg-background text-foreground enabled:hover:bg-muted data-on:z-10 data-on:border-border-strong data-on:bg-muted data-on:text-title-foreground' => $variant === 'outline',
        '-ms-px rounded-none first:ms-0 first:rounded-s-ui last:rounded-e-ui' => $variant === 'outline' && ! $vertical,
        '-mt-px rounded-none first:mt-0 first:rounded-t-ui last:rounded-b-ui' => $variant === 'outline' && $vertical,
    ]) }}>
    {{ $slot }}
    @if ($vertical && $single)
        <span aria-hidden="true" class="ms-auto hidden size-3.5 shrink-0 iconify ph--check-bold text-primary in-data-on:flex"></span>
    @endif
</button>

/**
 * Groupes de boutons à presser Flexiwind : <x-ui.toggle-group>.
 *
 * `single` se comporte comme des boutons radio (une valeur, les flèches la
 * déplacent) ; `multiple` comme une barre d'outils (un tableau, les flèches
 * déplacent seulement le focus). Une seule tabulation entre dans le groupe.
 */

export function ToggleGroupPlugin(Alpine) {
    Alpine.data("fwToggleGroup", toggleGroup);
}

function toggleGroup(config = {}) {
    const multiple = !!config.multiple;
    let root = null;

    return {
        value: config.value ?? (multiple ? [] : null),
        inputName: config.name ? config.name + (multiple && !config.name.endsWith("[]") ? "[]" : "") : null,

        init() {
            root = this.$el;
            this.$nextTick(() => this.syncTabStops());
            this.$watch("value", () => this.$nextTick(() => this.syncTabStops()));
        },

        get selected() {
            if (Array.isArray(this.value)) {
                return this.value.map(String);
            }

            return this.value === null || this.value === undefined || this.value === "" ? [] : [String(this.value)];
        },

        get formValues() {
            return this.selected.length ? this.selected : multiple ? [] : [""];
        },

        fwIsOn(value) {
            return this.selected.includes(String(value));
        },

        fwToggle(value) {
            value = String(value);

            if (multiple) {
                this.value = this.fwIsOn(value) ? this.selected.filter((item) => item !== value) : [...this.selected, value];

                return;
            }

            // `required` : la valeur choisie ne se retire pas.
            if (this.fwIsOn(value)) {
                if (!config.required) {
                    this.value = null;
                }

                return;
            }

            this.value = value;
        },

        stops() {
            return [...root.querySelectorAll("[data-toggle-stop]")].filter((stop) => !stop.disabled);
        },

        syncTabStops(current = null) {
            const stops = this.stops();
            const active = current ?? stops.find((stop) => stop.hasAttribute("data-on")) ?? stops[0];

            stops.forEach((stop) => stop.setAttribute("tabindex", stop === active ? "0" : "-1"));
        },

        onKeydown(event) {
            const stops = this.stops();
            const index = stops.indexOf(document.activeElement);

            if (index === -1) {
                return;
            }

            const moves = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
            let next = null;

            if (event.key in moves) {
                // De droite à gauche, les flèches horizontales s'inversent.
                const flipped = getComputedStyle(root).direction === "rtl" && (event.key === "ArrowLeft" || event.key === "ArrowRight");
                const step = flipped ? -moves[event.key] : moves[event.key];
                next = stops[(index + step + stops.length) % stops.length];
            } else if (event.key === "Home") {
                next = stops[0];
            } else if (event.key === "End") {
                next = stops[stops.length - 1];
            }

            if (!next) {
                return;
            }

            event.preventDefault();
            this.syncTabStops(next);
            next.focus();

            // Comme des boutons radio : le focus emporte la valeur.
            if (!multiple) {
                this.value = next.dataset.value;
            }
        },
    };
}
